-- JumpShip SQLite schema, generated by docs/rust-migration/gen_contract.py from
-- backend/models/db_models.py (SQLAlchemy metadata, sqlite dialect). Do not edit by hand.
--
-- Conventions the Rust port must reproduce:
--   * Primary keys are TEXT uuid4 strings generated app-side (gen_uuid), except
--     user_profiles which /api/profile addresses as the fixed id 'singleton'.
--   * DateTime columns are stored by SQLAlchemy as 'YYYY-MM-DD HH:MM:SS[.ffffff]' text; server defaults use
--     CURRENT_TIMESTAMP (UTC, 'YYYY-MM-DD HH:MM:SS'). The API returns them via .isoformat() (no 'Z').
--     applications.applied_at is written with datetime.utcnow().
--   * JSON columns are TEXT holding JSON (SQLAlchemy JSON type on sqlite).
--   * onupdate=func.now() (updated_at) is applied by SQLAlchemy on UPDATE; there is no DB trigger.
--
-- Tables used by endpoints the frontend actually calls (see API.md):
--   applications        /api/applications*, /api/resume/generate-for-application, /api/interview/*
--   interview_sessions  /api/interview/*
--   user_profiles       /api/profile, /api/settings/llm-keys, tailored-resume contact context
--   generated_resumes   /api/resume/generate-for-application (insert only; list/download are unused)
-- Tables only touched by legacy/unused endpoints (can be dropped from a fresh port):
--   saved_jobs (/api/jobs/save*), resumes (/api/resume/upload), analyses (/api/analysis*),
--   settings (/api/settings/ai-keys, /platforms, /profile - legacy key/value store)

CREATE TABLE analyses (
	id VARCHAR NOT NULL,
	job_id VARCHAR NOT NULL,
	resume_id VARCHAR NOT NULL,
	job_title VARCHAR,
	company_name VARCHAR,
	score FLOAT,
	strengths JSON,
	gaps JSON,
	suggestions JSON,
	summary TEXT,
	keywords_matched JSON,
	keywords_missing JSON,
	tailored_resume TEXT,
	provider VARCHAR,
	analyzed_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY (id)
);
-- ORM (Python-side) defaults not in the DDL: id=gen_uuid, provider='ollama'

CREATE TABLE applications (
	id VARCHAR NOT NULL,
	job_id VARCHAR,
	job_title VARCHAR NOT NULL,
	company_name VARCHAR,
	job_url VARCHAR,
	site VARCHAR,
	status VARCHAR,
	is_easy_apply BOOLEAN,
	applied_at DATETIME,
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	notes TEXT,
	analysis_id VARCHAR,
	assessment_data JSON,
	match_score INTEGER,
	job_description TEXT,
	PRIMARY KEY (id)
);
-- ORM (Python-side) defaults not in the DDL: id=gen_uuid, status='saved', is_easy_apply=False, updated_at=<now() on every UPDATE>

CREATE TABLE generated_resumes (
	id VARCHAR NOT NULL,
	job_id VARCHAR,
	job_title VARCHAR,
	company VARCHAR,
	match_score INTEGER,
	markdown TEXT,
	pdf_path VARCHAR,
	provider VARCHAR,
	model VARCHAR,
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY (id)
);
-- ORM (Python-side) defaults not in the DDL: id=gen_uuid, job_title='', company='', match_score=0, provider='ollama', model=''
CREATE INDEX ix_generated_resumes_job_id ON generated_resumes (job_id);

CREATE TABLE interview_sessions (
	id VARCHAR NOT NULL,
	application_id VARCHAR NOT NULL,
	persona_name VARCHAR,
	persona_bio TEXT,
	session_context TEXT,
	interview_track VARCHAR,
	messages JSON,
	state VARCHAR,
	completed BOOLEAN,
	report JSON,
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY (id)
);
-- ORM (Python-side) defaults not in the DDL: id=gen_uuid, persona_name='', persona_bio='', interview_track='behavioral', messages=list, state='', completed=False, updated_at=<now() on every UPDATE>
CREATE INDEX ix_interview_sessions_application_id ON interview_sessions (application_id);

CREATE TABLE resumes (
	id VARCHAR NOT NULL,
	filename VARCHAR NOT NULL,
	content TEXT NOT NULL,
	file_path VARCHAR,
	uploaded_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY (id)
);
-- ORM (Python-side) defaults not in the DDL: id=gen_uuid

CREATE TABLE saved_jobs (
	id VARCHAR NOT NULL,
	title VARCHAR NOT NULL,
	company_name VARCHAR,
	job_url VARCHAR,
	job_url_direct VARCHAR,
	location_city VARCHAR,
	location_state VARCHAR,
	location_country VARCHAR,
	description TEXT,
	job_type VARCHAR,
	is_remote BOOLEAN,
	min_salary FLOAT,
	max_salary FLOAT,
	salary_interval VARCHAR,
	currency VARCHAR,
	site VARCHAR,
	company_industry VARCHAR,
	job_level VARCHAR,
	company_logo VARCHAR,
	date_posted VARCHAR,
	easy_apply BOOLEAN,
	saved_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	raw_data JSON,
	PRIMARY KEY (id)
);
-- ORM (Python-side) defaults not in the DDL: id=gen_uuid

CREATE TABLE settings (
	"key" VARCHAR NOT NULL,
	value TEXT,
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY ("key")
);
-- ORM (Python-side) defaults not in the DDL: updated_at=<now() on every UPDATE>

CREATE TABLE user_profiles (
	id VARCHAR NOT NULL,
	full_name VARCHAR,
	email VARCHAR,
	phone VARCHAR,
	linkedin_url VARCHAR,
	github_url VARCHAR,
	portfolio_url VARCHAR,
	location_city VARCHAR,
	location_state VARCHAR,
	location_country VARCHAR,
	work_authorization VARCHAR,
	willing_to_relocate BOOLEAN,
	preferred_work_mode VARCHAR,
	years_experience INTEGER,
	highest_degree VARCHAR,
	university VARCHAR,
	graduation_year INTEGER,
	salary_min INTEGER,
	salary_max INTEGER,
	salary_currency VARCHAR,
	custom_answers JSON,
	extra_info TEXT,
	llm_keys_encrypted TEXT,
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY (id)
);
-- ORM (Python-side) defaults not in the DDL: id=gen_uuid, willing_to_relocate=False, years_experience=0, salary_currency='USD', custom_answers=dict, updated_at=<now() on every UPDATE>

